/* Anniversaries, countdown/today states and local reminder inbox. */
(() => {
 const UI=window.PrototypeUI,R=window.PrototypeRecords,D=window.PrototypeDates,KEY='dujia-prototype-anniversaries',READ='dujia-prototype-reminder-reads',page=location.pathname.split('/').pop().slice(0,7),id=new URLSearchParams(location.search).get('id'),screen=document.querySelector('.screen');
 const all=()=>{const v=UI.read(KEY,[]);return Array.isArray(v)?v:[];},find=id=>all().find(v=>v.id===id),moments=()=>{const v=UI.read('dujia-prototype-moments',[]);return Array.isArray(v)?v:[];};
 function put(item){const data=all(),index=data.findIndex(v=>v.id===item.id);if(index<0)data.unshift(item);else data[index]=item;return UI.write(KEY,data);}
 const list=()=>all().length?'m04-p07.html':'m04-p08.html',route=item=>(D.occurrence(item)?.days===0?'m04-p11':'m04-p10')+'.html?id='+encodeURIComponent(item.id);
 if(localStorage.getItem(KEY)===null&&['m04-p05','m04-p07','m04-p10','m04-p11'].includes(page))put({id:'sample-anniversary-1',name:'相识纪念日',date:D.add(D.today(),page==='m04-p11'?0:3).iso,repeat:true,reminderDays:3,enabled:true,momentId:null,createdAt:Date.now()});
 function notices(){const active=all().map(item=>({item,when:D.occurrence(item)})).filter(v=>v.when&&v.item.enabled&&v.when.days>=0&&v.when.days<=v.item.reminderDays).map(v=>({id:v.item.id+':'+v.when.iso,targetId:v.item.id,title:v.item.name+(v.when.days?'还有 '+v.when.days+' 天':'就在今天'),body:'一起为 '+v.when.iso+' 留一段记录吧',url:route(v.item)}));const saved=UI.read(READ,[]);return [...active.map(n=>({...n,read:Array.isArray(saved)&&saved.some(v=>v.id===n.id)})),...(Array.isArray(saved)?saved:[]).filter(n=>find(n.targetId)&&!active.some(v=>v.id===n.id)).map(n=>({...n,read:true,url:route(find(n.targetId))}))];}
 window.PrototypeAnniversaries={all,find,put,list,route,notices};
 document.querySelector('.back')?.addEventListener('click',()=>UI.back(['m04-p05','m04-p06','m04-p07','m04-p08'].includes(page)?'m04-p01.html':page==='m04-p09'&&id&&find(id)?route(find(id)):list()));
 function missing(){screen.classList.add('prototype-anniversary-missing');const box=document.createElement('section');box.className='prototype-anniversary-state';const h=document.createElement('h2');h.textContent='这个纪念日已经不在了';const button=document.createElement('button');button.textContent='返回纪念日列表';button.onclick=()=>UI.go(list(),{force:true});box.append(h,button);screen.append(box);}
 if(page==='m04-p07'||page==='m04-p08'){
  if((page==='m04-p07'&&!all().length)||(page==='m04-p08'&&all().length)){UI.go(list(),{replace:true,force:true});return;}
  document.querySelectorAll('.plus,.add').forEach(b=>b.onclick=()=>UI.go('m04-p09.html'));
  if(page==='m04-p07'){
   const entries=document.querySelector('.entries');entries.classList.add('prototype-anniversary-entries');
   function render(){if(!all().length){UI.go('m04-p08.html',{replace:true,force:true});return;}entries.replaceChildren();const sorted=all().sort((a,b)=>(D.occurrence(a)?.days??Infinity)-(D.occurrence(b)?.days??Infinity)),first=sorted.find(v=>(D.occurrence(v)?.days??-1)>=0)||sorted[0],when=D.occurrence(first);document.querySelector('.hero-title').textContent=first.name;document.querySelector('.countdown').textContent=when?when.days===0?'今天是纪念日':when.days>0?'还有 '+when.days+' 天':'已经过 '+Math.abs(when.days)+' 天':'请重新设置日期';document.querySelector('.date-pill').textContent=when?.iso||'编辑日期';document.querySelector('.date-pill').onclick=()=>UI.go(route(first));
    for(const item of sorted){const article=document.createElement('article');article.className='prototype-anniversary-row';const button=document.createElement('button');button.className='prototype-anniversary-card';const name=document.createElement('b'),date=document.createElement('small');name.textContent=item.name;date.textContent=(item.repeat?'每年 ':'')+item.date;button.append(name,date);button.onclick=()=>UI.go(route(item));const toggle=document.createElement('button');toggle.className='prototype-anniversary-toggle';toggle.setAttribute('role','switch');toggle.setAttribute('aria-checked',String(item.enabled));toggle.setAttribute('aria-label',item.name+'提醒');toggle.textContent=item.enabled?'已开启':'已关闭';toggle.onclick=()=>UI.busy(toggle,'更新中…',()=>{if(UI.failNext('anniversary-toggle'))throw new Error('提醒设置未更新，请重试');if(!put({...item,enabled:!item.enabled}))return false;render();return true;});article.append(button,toggle);entries.append(article);}}
   const refresh=document.createElement('button');refresh.className='prototype-anniversary-refresh';refresh.textContent='↻';refresh.setAttribute('aria-label','刷新纪念日');screen.append(refresh);let loading=false;
   async function load(){if(loading)return;loading=true;refresh.disabled=true;entries.replaceChildren();entries.setAttribute('aria-busy','true');const text=document.createElement('p');text.textContent='正在打开纪念日…';text.setAttribute('role','status');entries.append(text);await new Promise(resolve=>setTimeout(resolve,400));loading=false;refresh.disabled=false;entries.removeAttribute('aria-busy');if(UI.failNext('anniversary-load')){entries.replaceChildren();const h=document.createElement('h2');h.textContent='纪念日暂时打不开';const retry=document.createElement('button');retry.textContent='重试加载纪念日';retry.onclick=load;entries.append(h,retry);}else render();}refresh.onclick=load;load();
  }
 }
 if(page==='m04-p09'){
  const existing=id?find(id):null;if(id&&!existing){missing();return;}const form=document.querySelector('#anniversary-form');form.elements.name.value=existing?.name||'';form.elements.date.value=existing?.date||D.today().iso;form.elements.repeat.checked=existing?.repeat??true;form.elements.reminder.value=existing?(existing.enabled?existing.reminderDays===0?'当天':`提前 ${existing.reminderDays} 天`:'不提醒'):'提前 3 天';
  const select=form.elements.moment;select.replaceChildren();const empty=document.createElement('option');empty.value='';empty.textContent='可选 · 关联一段章节';select.append(empty);for(const item of moments()){const option=document.createElement('option');option.value=item.id;option.textContent=item.name;select.append(option);}select.value=existing?.momentId||'';
  const leave=UI.guard(form,{fallback:existing?route(existing):list()});form.elements.date.readOnly=true;form.elements.date.onclick=async()=>{const input=document.createElement('input');input.type='date';input.value=form.elements.date.value;input.min='1900-01-01';input.setAttribute('aria-label','选择纪念日日期');const action=await UI.sheet({title:'纪念日日期',content:input,actions:[{label:'使用这个日期',value:'apply'}]});if(action==='apply'){if(!D.parse(input.value)){UI.fieldError(form.elements.date,'请选择有效日期');return;}form.elements.date.value=input.value;}};
  form.elements.name.addEventListener('input',()=>UI.fieldError(form.elements.name,''));form.addEventListener('submit',event=>{event.preventDefault();const name=form.elements.name.value.trim(),date=form.elements.date.value;if(!name||!D.parse(date)){const field=!name?form.elements.name:form.elements.date;UI.fieldError(field,!name?'请填写纪念日名称':'请选择有效日期');field.focus();return;}UI.busy(form.querySelector('.submit'),'保存中…',()=>{if(UI.failNext('anniversary-save'))throw new Error('纪念日未保存成功，请重试');const reminder=form.elements.reminder.value,item={...existing,id:existing?.id||'anniversary-'+crypto.randomUUID(),name,date,repeat:form.elements.repeat.checked,enabled:reminder!=='不提醒',reminderDays:reminder==='当天'?0:reminder==='提前 1 天'?1:3,momentId:select.value||null,createdAt:existing?.createdAt||Date.now(),updatedAt:Date.now()};if(!put(item))return false;leave.commit();UI.toast('纪念日已保存','success');return UI.go(existing?route(item):list(),{force:true});});});form.dataset.prototypeReady='true';
 }
 if(page==='m04-p10'||page==='m04-p11'){
  const item=find(id||'sample-anniversary-1');if(!item){missing();return;}const when=D.occurrence(item);if(!when){missing();return;}if((when.days===0)!==(page==='m04-p11')){UI.go(route(item),{replace:true,force:true});return;}
  document.querySelector('.title').textContent=item.name;document.querySelector('.date').textContent=when.iso;const recordURL='m03-p05.html?anniversary='+encodeURIComponent(item.id);
  const moment=moments().find(v=>v.id===item.momentId);
  if(page==='m04-p10'){document.querySelector('.still').textContent=when.days>=0?'还有':'已经过';document.querySelector('.number').textContent=Math.abs(when.days);document.querySelector('.new-record').onclick=()=>UI.go(recordURL);const related=document.querySelector('.related');related.classList.add('prototype-anniversary-related');related.replaceChildren();if(moment){const b=document.createElement('button');b.textContent=moment.name;b.onclick=()=>UI.go('m04-p03.html?id='+encodeURIComponent(moment.id));related.append(b);}for(const record of R.all().filter(v=>v.anniversaryId===item.id&&v.visibility==='shared'&&v.status!=='draft')){const b=document.createElement('button');b.textContent=record.title;b.onclick=()=>UI.go(R.route(record));related.append(b);}if(!related.children.length)related.textContent='还没有相关记录，写下一篇纪念日记吧';}
  else{const buttons=[...document.querySelectorAll('.actions button')];buttons[0].onclick=()=>UI.go(recordURL);buttons[1].textContent=moment?'查看这个时刻':'关联一个重要时刻';buttons[1].onclick=()=>UI.go(moment?'m04-p03.html?id='+encodeURIComponent(moment.id):'m04-p09.html?id='+encodeURIComponent(item.id));const back=document.createElement('button');back.className='prototype-anniversary-back';back.textContent='‹';back.setAttribute('aria-label','返回纪念日列表');back.onclick=()=>UI.back(list());screen.append(back);}
  const edit=document.createElement('button');edit.className='prototype-anniversary-edit';edit.textContent='编辑';edit.setAttribute('aria-label','编辑纪念日');edit.onclick=()=>UI.go('m04-p09.html?id='+encodeURIComponent(item.id));const more=document.createElement('button');more.id='more';more.className='prototype-anniversary-more';more.textContent='•••';more.setAttribute('aria-label','更多操作');screen.append(edit,more);more.onclick=async()=>{const action=await UI.sheet({title:'纪念日操作',actions:[{label:'删除纪念日',value:'delete',danger:true}]});if(action!=='delete'||!await UI.modal({title:'删除这个纪念日？',message:'相关时刻和日记仍保留。',confirm:'确认删除',cancel:'取消'}))return;UI.busy(more,'删除中…',()=>{if(UI.failNext('anniversary-delete'))throw new Error('删除没有完成，请重试');if(!UI.write(KEY,all().filter(v=>v.id!==item.id)))return false;return UI.go(list(),{force:true});});};
 }
 if(page==='m04-p05'||page==='m04-p06'){
  const values=notices();if((page==='m04-p05'&&!values.length)||(page==='m04-p06'&&values.length)){UI.go(values.length?'m04-p05.html':'m04-p06.html',{replace:true,force:true});return;}
  if(page==='m04-p06')document.querySelector('.go').onclick=()=>UI.go('m04-p01.html');
  else{document.querySelectorAll('.section-title,.read-item').forEach(v=>v.remove());const section=document.querySelector('.list');section.classList.add('prototype-reminder-list');section.setAttribute('aria-label','共同提醒');section.replaceChildren();for(const notice of values){const button=document.createElement('button');button.className='prototype-reminder-card';const title=document.createElement('b'),body=document.createElement('p');title.textContent=notice.title+(notice.read?' · 已读':'');body.textContent=notice.body;button.append(title,body);button.onclick=()=>{const saved=UI.read(READ,[]),data=Array.isArray(saved)?saved:[];if(!UI.write(READ,[...data.filter(v=>v.id!==notice.id),{...notice,read:true,readAt:Date.now()}]))return;UI.go(notice.url);};section.append(button);}}
 }
})();
